  this.people().reduce((sum, p) => sum + (this.cutCents().get(p.id) ?? 0), 0),
);
/** Everyone's settled-totals and open-totals, in cents, each simply added up (not trimmed). */
protected readonly splitTotal = computed(() => {
  const each = this.people().map((p) => this.splitOf(p));
  return {
    settled: each.reduce((sum, s) => sum + s.settled, 0),
    open: each.reduce((sum, s) => sum + s.open, 0),
  };
});
/** What is due on everyone's counting OPEN and PENDING claims, in cents, by age: the people's age
 *  buckets (0 to 30, 31 to 60, 61 or more days) each simply added up (not trimmed). */
protected readonly agedTotal = computed(() => {
  const total: [number, number, number] = [0, 0, 0];
  for (const p of this.people()) {
    const aged = this.agedOf(p);
    for (let i = 0; i < 3; i++) total[i] += aged[i];
  }
  return total;
});
/** How many of everyone's counting claims are overdue, and what is due on them, in cents (trimmed). */
protected readonly overdueTotal = computed(() => {
  const each = this.people().map((p) => this.overdueOf(p));
  return {
    count: each.reduce((sum, o) => sum + o.count, 0),
    cents: trimmedSum(each.map((o) => o.cents)),
  };
});
/** The signed-in user's own figures: the due-total and overdue-total of the person on the sheet who
 *  has the user's name, or else has it as an alias (as names are compared); null when there is none. */
protected readonly myFigures = computed(() => {
  const me = this.me();
  if (!me) return null;
  return { dueTotal: this.dueTotalOf(me) ?? 'n/a', overdueTotal: money(this.overdueOf(me).cents) };
});
/** The signed-in user's crew total: the due-totals of the crews led by the person who is the user (as
 *  their own figures find them), added up; blank when there is no such person or they lead no crew. */
protected readonly myCrewDueTotal = computed(() => {
  const me = this.me();
  if (!me) return '';
  const led = this.crewsService.crews().filter((c) => c.lead?.personId === me.id);
  if (led.length === 0) return '';
  const due = this.dueCentsById();
  return money(led.reduce((sum, c) => sum + crewDueCents(c, due), 0));
});
/** The ids of the people a restricted user may see listed: the person with their name and the leads
 *  and members of every crew that person leads or belongs to; none when there is no such person.
 *  A person they quick-added since the sheet was loaded is listed too, until it is re-loaded.
 *  Null when the user is not restricted, who sees everyone. */
private readonly visibleIds = computed<Set<number> | null>(() => {
  const user = this.session.user();
  if (user === null || this.roles().find((r) => r.user === user)?.role !== 'restricted') return null;
  const me = this.me();
  const ids = new Set<number>();
  this.quickAdded().forEach((id) => ids.add(id));
  if (!me) return ids;
  ids.add(me.id);
  for (const crew of this.crewsService.crews()) {
    const crewIds = [...(crew.lead ? [crew.lead.personId] : []), ...crew.members.map((m) => m.personId)];
    if (crewIds.includes(me.id)) crewIds.forEach((id) => ids.add(id));
  }
  return ids;
});
/** The roles given on the sheet, as read when it was loaded. */
private readonly roles = signal<RoleGiven[]>([]);
/** The person on the sheet who has the signed-in user's name, or else has it as an alias (as names are
 *  compared); null when there is none. */
private readonly me = computed(() => {
  const user = this.session.user();
  if (user === null) return null;
  const key = nameKey(user);
  const people = this.people();
  return people.find((p) => nameKey(p.name) === key) ?? people.find((p) => p.aliases.some((a) => nameKey(a) === key)) ?? null;
});
/** The figures of the sheet's descendants, added up, as read when the sheet was loaded. */
protected readonly descendants = signal<DescendantFigures>(NO_DESCENDANTS);
/** The consolidated figures: the sheet's own (as its header shows them) and its descendants', added up.
 *  While the sheet is read as of an earlier date they are the tree's as it stood then: the server adds the sheet's own in. */
protected readonly consolidated = computed(() => {
  const d = this.descendants();
  const own = !this.session.asOf();
  const people = own ? this.summaryPeople().filter((p) => !p.retired) : [];
  const claims = own ? this.claims() : [];
  const ownPeople = own ? this.people() : [];
  // The trim applies once over every person of the tree; a person is counted once across it.
  const due = [
    ...ownPeople.map((p) => this.dueCentsOf(p)).filter((c): c is number => c !== null),
    ...(d.dueFigures ?? []).map(cents),
  ];
  const overdue = [...ownPeople.map((p) => this.overdueOf(p).cents), ...(d.overdueFigures ?? []).map(cents)];
  return {
    peopleCount: own
      ? distinctPeople([...ownPeople.map((p) => [p.name, ...p.aliases].map(nameKey)), ...(d.nameKeys ?? [])])
      : d.peopleCount,
    dueTotal: own ? money(trimmedSum(due)) : d.dueTotal,
    overdueTotal: own ? money(trimmedSum(overdue)) : d.overdueTotal,
    grades: GRADES.map((grade) => ({
      grade,
      dueTotal: money(
        people.filter((p) => p.grade === grade).reduce((sum, p) => sum + (p.dueCents ?? 0), 0) +
          cents(d.gradeDueTotals[grade] ?? '0.00'),
      ),
    })),
    statuses: STATUSES.map((status) => ({
      status,
      count: claims.filter((c) => c.status === status).length + (d.statusCounts[status] ?? 0),
    })),
  };
});
