  await c.getByTestId('claim-share-pct').fill(share);
  await c.getByTestId('claim-share-add').click();
  return until(page, async () => (await shown(c.getByTestId('claim-shares'))) !== was, c.getByTestId('claim-error'), 'share claim');
}
